#!/usr/bin/env python3
"""Score rubric annotations and calculate two-annotator agreement.

Standard library only. Input CSV columns: report_id, annotator, field_id,
label, evidence_locator, notes. Labels must match schema/report-fields.json.
"""

from __future__ import annotations

import argparse
import csv
import json
import sys
from collections import Counter, defaultdict
from pathlib import Path
from typing import Any, Iterable


class DataError(ValueError):
    """Raised for invalid or incomplete annotation data."""


def load_schema(path: str | Path) -> dict[str, Any]:
    with Path(path).open(encoding="utf-8") as handle:
        schema = json.load(handle)
    fields = schema.get("fields")
    labels = schema.get("labels")
    dimensions = schema.get("dimensions")
    if not isinstance(fields, list) or not fields:
        raise DataError("Schema must contain a non-empty fields list")
    if not isinstance(labels, dict) or not labels:
        raise DataError("Schema must contain a non-empty labels object")
    if not isinstance(dimensions, list) or not dimensions:
        raise DataError("Schema must contain a non-empty dimensions list")
    seen = set()
    for field in fields:
        field_id = field.get("id")
        dimension = field.get("dimension")
        if not field_id or field_id in seen:
            raise DataError(f"Missing or duplicate field id: {field_id!r}")
        if dimension not in dimensions:
            raise DataError(f"Unknown dimension for {field_id}: {dimension!r}")
        seen.add(field_id)
    for label, value in labels.items():
        if not isinstance(value, (int, float)) or not 0 <= value <= 1:
            raise DataError(f"Invalid numeric value for label {label!r}")
    return schema


def read_annotations(path: str | Path, schema: dict[str, Any]) -> list[dict[str, Any]]:
    field_ids = {field["id"] for field in schema["fields"]}
    labels = schema["labels"]
    required = {
        "report_id", "annotator", "field_id", "label", "evidence_locator", "notes"
    }
    rows: list[dict[str, Any]] = []
    seen = set()
    with Path(path).open(encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle)
        missing = required - set(reader.fieldnames or [])
        if missing:
            raise DataError(f"Missing CSV columns: {', '.join(sorted(missing))}")
        for line_number, raw in enumerate(reader, start=2):
            row = {key: (raw.get(key) or "").strip() for key in required}
            for key in ("report_id", "annotator", "field_id", "label"):
                if not row[key]:
                    raise DataError(f"Line {line_number}: empty {key}")
            if row["field_id"] not in field_ids:
                raise DataError(f"Line {line_number}: unknown field {row['field_id']!r}")
            if row["label"] not in labels:
                raise DataError(f"Line {line_number}: unknown label {row['label']!r}")
            key = (row["report_id"], row["annotator"], row["field_id"])
            if key in seen:
                raise DataError(f"Line {line_number}: duplicate annotation {key!r}")
            seen.add(key)
            row["value"] = float(labels[row["label"]])
            rows.append(row)
    if not rows:
        raise DataError("Annotation file contains no rows")
    return rows


def require_complete(rows: list[dict[str, Any]], schema: dict[str, Any]) -> None:
    """Require exactly one label per field for every included report/annotator."""
    expected = {field["id"] for field in schema["fields"]}
    grouped: dict[tuple[str, str], set[str]] = defaultdict(set)
    for row in rows:
        grouped[(row["report_id"], row["annotator"])].add(row["field_id"])
    problems = []
    for (report_id, annotator), actual in sorted(grouped.items()):
        if actual != expected:
            missing = sorted(expected - actual)
            extra = sorted(actual - expected)
            problems.append(
                f"{report_id}/{annotator}: missing={missing}, extra={extra}"
            )
    if problems:
        raise DataError("Incomplete annotations: " + "; ".join(problems))


def coverage(rows: Iterable[dict[str, Any]], schema: dict[str, Any]) -> dict[str, Any]:
    rows = list(rows)
    if not rows:
        raise DataError("No annotations selected")
    require_complete(rows, schema)
    by_report_annotator = {
        (row["report_id"], row["annotator"]) for row in rows
    }
    if len({report for report, _ in by_report_annotator}) != len(by_report_annotator):
        raise DataError(
            "Coverage requires one annotator/adjudicated series per report; "
            "select one with --annotator"
        )
    fields = schema["fields"]
    dimensions = schema["dimensions"]
    label_names = list(schema["labels"])
    by_field: dict[str, list[dict[str, Any]]] = defaultdict(list)
    by_report: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for row in rows:
        by_field[row["field_id"]].append(row)
        by_report[row["report_id"]].append(row)

    def summarize(selected: list[dict[str, Any]]) -> dict[str, Any]:
        counts = Counter(row["label"] for row in selected)
        return {
            "n": len(selected),
            "coverage": sum(row["value"] for row in selected) / len(selected),
            "label_counts": {label: counts.get(label, 0) for label in label_names},
        }

    field_results = {}
    for field in fields:
        result = summarize(by_field[field["id"]])
        result["dimension"] = field["dimension"]
        field_results[field["id"]] = result
    dimension_results = {}
    for dimension in dimensions:
        ids = {field["id"] for field in fields if field["dimension"] == dimension}
        selected = [row for row in rows if row["field_id"] in ids]
        dimension_results[dimension] = summarize(selected)
    return {
        "report_count": len(by_report),
        "fields": field_results,
        "dimensions": dimension_results,
        "reports": {
            report_id: summarize(report_rows)
            for report_id, report_rows in sorted(by_report.items())
        },
    }


def cohen_kappa(pairs: list[tuple[str, str]], categories: list[str]) -> dict[str, Any]:
    if not pairs:
        raise DataError("No paired annotations")
    n = len(pairs)
    counts_a = Counter(a for a, _ in pairs)
    counts_b = Counter(b for _, b in pairs)
    observed = sum(a == b for a, b in pairs) / n
    expected = sum((counts_a[c] / n) * (counts_b[c] / n) for c in categories)
    kappa = None if expected == 1 else (observed - expected) / (1 - expected)
    return {
        "n": n,
        "observed_agreement": observed,
        "expected_agreement": expected,
        "cohens_kappa": kappa,
        "counts_a": {c: counts_a.get(c, 0) for c in categories},
        "counts_b": {c: counts_b.get(c, 0) for c in categories},
        "note": "Kappa is undefined when expected agreement is 1; inspect counts."
        if kappa is None else None,
    }


def agreement(
    rows: list[dict[str, Any]], schema: dict[str, Any], annotator_a: str, annotator_b: str
) -> dict[str, Any]:
    require_complete(rows, schema)
    selected = [row for row in rows if row["annotator"] in {annotator_a, annotator_b}]
    if not selected:
        raise DataError("Neither requested annotator has annotations")
    require_complete(selected, schema)
    lookup = {
        (row["report_id"], row["annotator"], row["field_id"]): row["label"]
        for row in selected
    }
    reports_a = {row["report_id"] for row in selected if row["annotator"] == annotator_a}
    reports_b = {row["report_id"] for row in selected if row["annotator"] == annotator_b}
    if not reports_a or not reports_b:
        raise DataError("Both requested annotators must have annotations")
    if reports_a != reports_b:
        raise DataError(
            f"Annotator report sets differ: only_a={sorted(reports_a-reports_b)}, "
            f"only_b={sorted(reports_b-reports_a)}"
        )
    categories = list(schema["labels"])
    results = {}
    all_pairs = []
    for field in schema["fields"]:
        field_id = field["id"]
        pairs = [
            (lookup[(report, annotator_a, field_id)],
             lookup[(report, annotator_b, field_id)])
            for report in sorted(reports_a)
        ]
        results[field_id] = cohen_kappa(pairs, categories)
        all_pairs.extend(pairs)
    return {
        "annotator_a": annotator_a,
        "annotator_b": annotator_b,
        "report_count": len(reports_a),
        "fields": results,
        "pooled": cohen_kappa(all_pairs, categories),
        "warning": "Per-field kappa is unstable with few reports or rare labels; "
                   "report raw counts and do not interpret pooled kappa as a quality threshold.",
    }


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    subparsers = parser.add_subparsers(dest="command", required=True)
    for command in ("score", "agreement"):
        sub = subparsers.add_parser(command)
        sub.add_argument("--schema", required=True)
        sub.add_argument("--annotations", required=True)
        if command == "score":
            sub.add_argument("--annotator", help="Select one raw annotation series")
        else:
            sub.add_argument("--a", required=True, help="First annotator ID")
            sub.add_argument("--b", required=True, help="Second annotator ID")
    return parser


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    try:
        schema = load_schema(args.schema)
        rows = read_annotations(args.annotations, schema)
        if args.command == "score":
            if args.annotator:
                rows = [row for row in rows if row["annotator"] == args.annotator]
                if not rows:
                    raise DataError(f"No annotations for {args.annotator!r}")
            result = coverage(rows, schema)
        else:
            result = agreement(rows, schema, args.a, args.b)
        json.dump(result, sys.stdout, indent=2, allow_nan=False)
        sys.stdout.write("\n")
        return 0
    except (DataError, OSError, json.JSONDecodeError) as exc:
        parser.exit(2, f"error: {exc}\n")


if __name__ == "__main__":
    raise SystemExit(main())
